sys_script.script:
(function executeRule(current, previous) {

    // Check if caller_id is empty or null
    if (current.caller_id.nil()) {

        // Get the currently logged-in user's sys_id
        var currentUser = gs.getUserID();

        // Validate that we have a valid user ID
        if (currentUser && currentUser !== '') {

            // Set the caller_id to the current user
            current.caller_id = currentUser;

            // Optional: Add a work note for audit purposes
            current.work_notes = "Caller automatically set to current user: " + gs.getUserName();
        }
    }

})(current, previous);
